    #[test]
    fn cloud_actions_catalog_is_the_exposed_registry_subset() {
        let expected_surface: std::collections::HashSet<&str> = [
            "create_tenant",
            "vault_put",
            "run_node",
            "get_ilk",
            "delete_ilk",
            "restore_ilk",
            "delete_tenant",
            "restore_tenant",
            "vault_list",
            "vault_delete",
            "update_tenant",
            "set_ilk_tenant",
            "vault_assign",
            "get_tenant",
            "list_tenants",
            "list_tenant_nodes",
            "get_node_status",
            "start_node",
            "kill_node",
            "get_llm_usage",
        ]
        .into_iter()
        .collect();
        let configured_surface: std::collections::HashSet<&str> =
            IO_CLOUD_EXPOSED_ACTIONS.iter().copied().collect();
        assert_eq!(configured_surface, expected_surface);

        // Every IO.cloud-exposed action must exist in the registry, else a typo would silently
        // drop it from Cloud's discoverable surface (and later from the authz gate).
        let registry: std::collections::HashSet<&str> =
            INTERNAL_ACTION_REGISTRY.iter().map(|s| s.action).collect();
        for action in IO_CLOUD_EXPOSED_ACTIONS {
            assert!(
                registry.contains(action),
                "IO_CLOUD_EXPOSED_ACTIONS lists '{action}' not in INTERNAL_ACTION_REGISTRY"
            );
        }
        // The capability projection returns exactly the exposed set.
        let (status, body) = build_cloud_actions_catalog_response();
        assert_eq!(status, 200);
        let v: serde_json::Value = serde_json::from_str(&body).unwrap();
        assert_eq!(v["action"], "list_cloud_actions");
        let got: std::collections::HashSet<&str> = v["payload"]["actions"]
            .as_array()
            .unwrap()
            .iter()
            .map(|a| a["action"].as_str().unwrap())
            .collect();
        assert_eq!(got, expected_surface);
    }

    #[test]
    fn externalize_authz_gate_io_prefix_and_ownership() {
        let owner = "IO.cloud@motherbee";
        // Trusted internal path (no router-stamped origin) is always allowed.
        assert!(authorize_channel_command(None, owner).is_ok());
        // The owner externalizing its own channel is allowed (I1 + I8).
        assert!(authorize_channel_command(Some("IO.cloud@motherbee"), owner).is_ok());
        // A non-IO node is rejected (I1) even if the name matched some owner.
        assert!(authorize_channel_command(Some("SY.admin@motherbee"), owner).is_err());
        assert!(authorize_channel_command(Some("AI.sales@motherbee"), owner).is_err());
        // An IO node may NOT externalize someone else's channel (I8).
        assert!(authorize_channel_command(Some("IO.other@motherbee"), owner).is_err());
        // Same node name, different hive is still a different node — rejected (I8, exact match).
        assert!(authorize_channel_command(Some("IO.cloud@worker1"), owner).is_err());
    }

